1	package com.example.starter.exposure.exposure;
2	
3	import com.example.starter.exposure.domain.Campaign;
4	import com.example.starter.exposure.domain.Reservation;
5	import com.example.starter.exposure.domain.ReservationStatus;
6	import com.example.starter.exposure.repo.CampaignRepository;
7	import com.example.starter.exposure.repo.IdempotencyRepository;
8	import com.example.starter.exposure.repo.IdempotencyRepository.IdempotencyRecord;
9	import com.example.starter.exposure.repo.LedgerRepository;
10	import com.example.starter.exposure.repo.ReservationRepository;
11	import com.example.starter.exposure.web.ApiException;
12	import com.example.starter.exposure.web.ApplyExposureRequest;
13	import com.example.starter.exposure.web.CampaignResponse;
14	import com.example.starter.exposure.web.CreateCampaignRequest;
15	import com.example.starter.exposure.web.QuotaResponse;
16	import com.example.starter.exposure.web.ReservationActionRequest;
17	import com.example.starter.exposure.web.ReservationResponse;
18	import com.fasterxml.jackson.databind.ObjectMapper;
19	import org.springframework.dao.DuplicateKeyException;
20	import org.springframework.http.HttpStatus;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.support.TransactionTemplate;
23	
24	import java.time.Clock;
25	import java.time.LocalDate;
26	import java.util.List;
27	import java.util.UUID;
28	import java.util.function.Supplier;
29	
30	/**
31	 * 公告曝光频控业务服务实现。
32	 *
33	 * <p>所有写操作以 requestId 为全局幂等键：同键同参重放原成功结果，异参 409；
34	 * 业务失败随事务回滚，不占幂等键。所有操作与额度查询先结算相关过期预占，
35	 * 不依赖后台定时器。终态竞争由行锁 + 状态 CAS 保证只允许一个终态。</p>
36	 */
37	@Service
38	public class ExposureServiceImpl implements ExposureService {
39	
40	    static final int RESERVATION_TTL_MILLIS = 60_000;
41	
42	    /** 并发同键竞争时等待胜出事务提交的最大时长。 */
43	    private static final long IDEMPOTENT_WAIT_MILLIS = 10_000L;
44	
45	    private final Clock clock;
46	    private final CampaignRepository campaignRepository;
47	    private final ReservationRepository reservationRepository;
48	    private final LedgerRepository ledgerRepository;
49	    private final IdempotencyRepository idempotencyRepository;
50	    private final ObjectMapper objectMapper;
51	    private final TransactionTemplate txTemplate;
52	
53	    public ExposureServiceImpl(Clock clock,
54	                               CampaignRepository campaignRepository,
55	                               ReservationRepository reservationRepository,
56	                               LedgerRepository ledgerRepository,
57	                               IdempotencyRepository idempotencyRepository,
58	                               ObjectMapper objectMapper,
59	                               TransactionTemplate txTemplate) {
60	        this.clock = clock;
61	        this.campaignRepository = campaignRepository;
62	        this.reservationRepository = reservationRepository;
63	        this.ledgerRepository = ledgerRepository;
64	        this.idempotencyRepository = idempotencyRepository;
65	        this.objectMapper = objectMapper;
66	        this.txTemplate = txTemplate;
67	    }
68	
69	    @Override
70	    public CampaignResponse createCampaign(CreateCampaignRequest request) {
71	        String fingerprint = request.campaignId() + "|" + request.dailyTotalCap() + "|"
72	                + request.perVisitorDailyCap();
73	        return runIdempotent(request.requestId(), Operation.CREATE_CAMPAIGN, fingerprint,
74	                CampaignResponse.class, () -> {
75	                    if (campaignRepository.findById(request.campaignId()).isPresent()) {
76	                        throw new ApiException(HttpStatus.CONFLICT,
77	                                "campaign already exists: " + request.campaignId());
78	                    }
79	                    Campaign campaign = new Campaign(
80	                            request.campaignId(),
81	                            request.dailyTotalCap(),
82	                            request.perVisitorDailyCap(),
83	                            clock.millis());
84	                    try {
85	                        campaignRepository.insert(campaign);
86	                    } catch (DuplicateKeyException duplicateCampaign) {
87	                        // 并发创建同一 campaignId：明确返回 409，而非误报幂等键冲突
88	                        throw new ApiException(HttpStatus.CONFLICT,
89	                                "campaign already exists: " + request.campaignId());
90	                    }
91	                    return CampaignResponse.from(campaign);
92	                });
93	    }
94	
95	    @Override
96	    public ReservationResponse apply(ApplyExposureRequest request) {
97	        String fingerprint = request.campaignId() + "|" + request.visitorId();
98	        return runIdempotent(request.requestId(), Operation.APPLY, fingerprint,
99	                ReservationResponse.class, () -> {
100	                    long now = clock.millis();
101	                    LocalDate utcDate = LocalDate.now(clock);
102	                    Campaign campaign = requireCampaign(request.campaignId());
103	
104	                    // 先结算该公告相关过期预占并释放额度
105	                    settleExpired(campaign.campaignId(), now);
106	
107	                    // 固定加锁顺序：公告当日总账 -> 访客当日账，避免死锁
108	                    ledgerRepository.ensureTotalRow(campaign.campaignId(), utcDate);
109	                    ledgerRepository.ensureVisitorRow(campaign.campaignId(), request.visitorId(), utcDate);
110	                    int usedTotal = ledgerRepository.lockUsedTotal(campaign.campaignId(), utcDate);
111	                    int usedVisitor = ledgerRepository.lockUsedVisitor(
112	                            campaign.campaignId(), request.visitorId(), utcDate);
113	
114	                    // 任一额度已满则 429，两个额度均不增加（尚未写入）
115	                    if (usedTotal + 1 > campaign.dailyTotalCap()
116	                            || usedVisitor + 1 > campaign.perVisitorDailyCap()) {
117	                        throw new ApiException(HttpStatus.TOO_MANY_REQUESTS,
118	                                "exposure quota exhausted for campaign " + campaign.campaignId());
119	                    }
120	                    ledgerRepository.addTotal(campaign.campaignId(), utcDate, 1);
121	                    ledgerRepository.addVisitor(campaign.campaignId(), request.visitorId(), utcDate, 1);
122	
123	                    String reservationId = UUID.randomUUID().toString().replace("-", "");
124	                    Reservation reservation = new Reservation(
125	                            reservationId,
126	                            campaign.campaignId(),
127	                            request.visitorId(),
128	                            java.sql.Date.valueOf(utcDate),
129	                            ReservationStatus.RESERVED,
130	                            now,
131	                            now + RESERVATION_TTL_MILLIS,
132	                            null);
133	                    reservationRepository.insert(reservation);
134	                    return ReservationResponse.from(reservation);
135	                });
136	    }
137	
138	    @Override
139	    public ReservationResponse confirm(String reservationId, ReservationActionRequest request) {
140	        String fingerprint = reservationId;
141	        return runIdempotent(request.requestId(), Operation.CONFIRM, fingerprint,
142	                ReservationResponse.class, () -> transition(reservationId, true));
143	    }
144	
145	    @Override
146	    public ReservationResponse cancel(String reservationId, ReservationActionRequest request) {
147	        String fingerprint = reservationId;
148	        return runIdempotent(request.requestId(), Operation.CANCEL, fingerprint,
149	                ReservationResponse.class, () -> transition(reservationId, false));
150	    }
151	
152	    @Override
153	    public ReservationResponse getReservation(String reservationId) {
154	        return txTemplate.execute(status -> {
155	            Reservation locked = reservationRepository.lockById(reservationId)
156	                    .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND,
157	                            "reservation not found: " + reservationId));
158	            expireIfDue(locked, clock.millis());
159	            return ReservationResponse.from(
160	                    reservationRepository.lockById(reservationId).orElseThrow());
161	        });
162	    }
163	
164	    @Override
165	    public QuotaResponse queryQuota(String campaignId, String visitorId, LocalDate requestedDate) {
166	        return txTemplate.execute(status -> {
167	            Campaign campaign = requireCampaign(campaignId);
168	            long now = clock.millis();
169	            LocalDate utcDate = requestedDate != null ? requestedDate : LocalDate.now(clock);
170	
171	            settleExpired(campaignId, now);
172	
173	            int usedTotal = ledgerRepository.getUsedTotal(campaignId, utcDate);
174	            if (visitorId == null || visitorId.isBlank()) {
175	                return new QuotaResponse(
176	                        campaignId, null, utcDate,
177	                        campaign.dailyTotalCap(), usedTotal,
178	                        campaign.dailyTotalCap() - usedTotal,
179	                        null, null, null, now);
180	            }
181	            int usedVisitor = ledgerRepository.getUsedVisitor(campaignId, visitorId, utcDate);
182	            return new QuotaResponse(
183	                    campaignId, visitorId, utcDate,
184	                    campaign.dailyTotalCap(), usedTotal,
185	                    campaign.dailyTotalCap() - usedTotal,
186	                    campaign.perVisitorDailyCap(), usedVisitor,
187	                    campaign.perVisitorDailyCap() - usedVisitor,
188	                    now);
189	        });
190	    }
191	
192	    // ---- 内部辅助（作用域末尾） ----
193	
194	    /** 幂等操作类型，同时标识存储响应的反序列化类型。 */
195	    private enum Operation {
196	        CREATE_CAMPAIGN,
197	        APPLY,
198	        CONFIRM,
199	        CANCEL
200	    }
201	
202	    /**
203	     * 在事务内执行业务并维护幂等记录；业务变更与去重结果原子提交。
204	     * 并发同键插入冲突时等待胜出事务提交后重放其结果。
205	     */
206	    private <T> T runIdempotent(String requestId, Operation operation, String fingerprint,
207	                                Class<T> responseType, Supplier<T> action) {
208	        long deadline = System.currentTimeMillis() + IDEMPOTENT_WAIT_MILLIS;
209	        while (true) {
210	            try {
211	                return txTemplate.execute(status -> {
212	                    var existing = idempotencyRepository.lockById(requestId);
213	                    if (existing.isPresent()) {
214	                        IdempotencyRecord record = existing.get();
215	                        if (!record.operation().equals(operation.name())
216	                                || !record.requestFingerprint().equals(fingerprint)) {
217	                            throw new ApiException(HttpStatus.CONFLICT,
218	                                    "idempotency key reused with different parameters: " + requestId);
219	                        }
220	                        try {
221	                            return objectMapper.readValue(record.responseJson(), responseType);
222	                        } catch (Exception e) {
223	                            throw new IllegalStateException("failed to replay idempotent response", e);
224	                        }
225	                    }
226	                    T result = action.get();
227	                    idempotencyRepository.insert(new IdempotencyRecord(
228	                            requestId, operation.name(), fingerprint, writeJson(result)), clock.millis());
229	                    return result;
230	                });
231	            } catch (DuplicateKeyException duplicate) {
232	                // 同键并发事务抢先插入（可能尚未提交），等待后重放
233	                if (System.currentTimeMillis() >= deadline) {
234	                    throw new ApiException(HttpStatus.CONFLICT,
235	                            "concurrent idempotency key conflict: " + requestId);
236	                }
237	                try {
238	                    Thread.sleep(5L);
239	                } catch (InterruptedException interrupted) {
240	                    Thread.currentThread().interrupt();
241	                    throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR, "interrupted");
242	                }
243	            }
244	        }
245	    }
246	
247	    /**
248	     * 确认/取消状态机。调用前已持幂等键；行锁 + CAS 保证并发只有一个终态。
249	     *
250	     * @param isConfirm true=确认，false=取消
251	     */
252	    private ReservationResponse transition(String reservationId, boolean isConfirm) {
253	        long now = clock.millis();
254	        Reservation current = reservationRepository.lockById(reservationId)
255	                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND,
256	                        "reservation not found: " + reservationId));
257	
258	        // 仅结算本单（本事务已持其行锁，加锁顺序保持为 预占单 -> 总账 -> 访客账，避免死锁）
259	        expireIfDue(current, now);
260	        current = reservationRepository.lockById(reservationId).orElseThrow();
261	
262	        if (current.status() == ReservationStatus.RESERVED) {
263	            // 结算后仍为 RESERVED 说明 now < expiresAt，确认严格要求在到期时刻之前
264	            if (isConfirm) {
265	                if (!reservationRepository.compareAndSetStatus(
266	                        reservationId, ReservationStatus.RESERVED, ReservationStatus.CONFIRMED, now)) {
267	                    throw new ApiException(HttpStatus.CONFLICT, "reservation state changed concurrently");
268	                }
269	            } else {
270	                if (!reservationRepository.compareAndSetStatus(
271	                        reservationId, ReservationStatus.RESERVED, ReservationStatus.CANCELLED, now)) {
272	                    throw new ApiException(HttpStatus.CONFLICT, "reservation state changed concurrently");
273	                }
274	                // 取消释放两级额度；固定顺序先总账后访客账
275	                ledgerRepository.releaseTotal(current.campaignId(), current.utcDate().toLocalDate());
276	                ledgerRepository.releaseVisitor(
277	                        current.campaignId(), current.visitorId(), current.utcDate().toLocalDate());
278	            }
279	        } else if (current.status() == ReservationStatus.CONFIRMED
280	                || current.status() == ReservationStatus.CANCELLED
281	                || current.status() == ReservationStatus.EXPIRED) {
282	            boolean sameTerminal = isConfirm
283	                    ? current.status() == ReservationStatus.CONFIRMED
284	                    : current.status() == ReservationStatus.CANCELLED;
285	            if (!sameTerminal) {
286	                throw new ApiException(HttpStatus.CONFLICT,
287	                        "reservation is " + current.status() + ", cannot "
288	                                + (isConfirm ? "confirm" : "cancel"));
289	            }
290	            // 重复同类终态操作：返回原状态，不重复释放额度
291	        } else {
292	            throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR,
293	                    "unexpected reservation status: " + current.status());
294	        }
295	
296	        Reservation result = reservationRepository.lockById(reservationId).orElseThrow();
297	        return ReservationResponse.from(result);
298	    }
299	
300	    /**
301	     * 结算某公告当前已到期（now &gt;= expiresAt）但仍为 RESERVED 的预占：
302	     * 行锁查出后逐个 CAS 为 EXPIRED，仅 CAS 成功者释放两级额度，杜绝重复释放。
303	     */
304	    private void settleExpired(String campaignId, long now) {
305	        List<Reservation> expired = reservationRepository.lockExpiredReserved(campaignId, now);
306	        for (Reservation reservation : expired) {
307	            expireIfDue(reservation, now);
308	        }
309	    }
310	
311	    /**
312	     * 若传入预占单（调用方已持其行锁）已到期，则 CAS 转 EXPIRED 并释放两级额度；
313	     * 未到期或已非 RESERVED 则不做任何变更。
314	     */
315	    private void expireIfDue(Reservation reservation, long now) {
316	        if (reservation.status() == ReservationStatus.RESERVED
317	                && now >= reservation.expiresAtUtc()) {
318	            boolean won = reservationRepository.compareAndSetStatus(
319	                    reservation.reservationId(),
320	                    ReservationStatus.RESERVED,
321	                    ReservationStatus.EXPIRED,
322	                    now);
323	            if (won) {
324	                LocalDate utcDate = reservation.utcDate().toLocalDate();
325	                ledgerRepository.releaseTotal(reservation.campaignId(), utcDate);
326	                ledgerRepository.releaseVisitor(
327	                        reservation.campaignId(), reservation.visitorId(), utcDate);
328	            }
329	        }
330	    }
331	
332	    private Campaign requireCampaign(String campaignId) {
333	        return campaignRepository.findById(campaignId)
334	                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND,
335	                        "campaign not found: " + campaignId));
336	    }
337	
338	    private Reservation requireReservation(String reservationId) {
339	        return reservationRepository.findById(reservationId)
340	                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND,
341	                        "reservation not found: " + reservationId));
342	    }
343	
344	    private String writeJson(Object value) {
345	        try {
346	            return objectMapper.writeValueAsString(value);
347	        } catch (Exception e) {
348	            throw new IllegalStateException("failed to serialize response", e);
349	        }
350	    }
351	}
